import java.util.*;
public class MovieTicketCounter { abstract static class Ticket{int n;Ticket(int n){this.n=n;}abstract double amount();}static class Regular extends Ticket{Regular(int n){super(n);}double amount(){return n*(150+20);}}static class Premium extends Ticket{Premium(int n){super(n);}double amount(){return n*(250+20);}}static class Recliner extends Ticket{Recliner(int n){super(n);}double amount(){return n*(400+20);}}public static void main(String[]a){Scanner s=new Scanner(System.in);int n=s.nextInt();double t=0;while(n-->0){String x=s.next();int c=s.nextInt();Ticket q=x.equals("REGULAR")?new Regular(c):x.equals("PREMIUM")?new Premium(c):new Recliner(c);double r=q.amount();t+=r;System.out.printf("%s: %.2f%n",x,r);}System.out.printf("Total: %.2f%n",t);}}
